import{_ as e,o as a,c as i,a3 as n}from"./chunks/framework.CWCEHGF4.js";const r="/MeshPaintingDoc/paint-target/01-add-component.png",o="/MeshPaintingDoc/paint-target/02-target-settings.png",s="/MeshPaintingDoc/paint-target/03-mesh-targets.png",d="/MeshPaintingDoc/paint-target/04-events.png",f=JSON.parse('{"title":"RuntimeMeshPaintTargetComponent","description":"","frontmatter":{},"headers":[],"relativePath":"systems/paint-target.md","filePath":"systems/paint-target.md","lastUpdated":1784811592000}'),l={name:"systems/paint-target.md"};function c(h,t,p,m,u,g){return a(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="runtimemeshpainttargetcomponent" tabindex="-1">RuntimeMeshPaintTargetComponent <a class="header-anchor" href="#runtimemeshpainttargetcomponent" aria-label="Permalink to &quot;RuntimeMeshPaintTargetComponent&quot;">​</a></h1><p><code>RuntimeMeshPaintTargetComponent</code> is the component that makes an actor paintable.</p><p>Add it to the actor that owns the mesh you want to paint. At runtime, the component creates the paint render targets, binds them to the mesh material, resolves paint hits, and applies paint through the GPU painting path.</p><p><img src="'+r+'" alt="RuntimeMeshPaintTargetComponent added to an actor"></p><h2 id="what-it-does" tabindex="-1">What It Does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What It Does&quot;">​</a></h2><p>The paint target component is responsible for the mesh-side part of the system:</p><ul><li>Finds the mesh component that should receive paint.</li><li>Creates the runtime color render target.</li><li>Optionally creates the material settings render target.</li><li>Creates the brush preview mask render target.</li><li>Assigns those render targets to dynamic material instances.</li><li>Resolves hit data into UV and surface data.</li><li>Applies paint commands locally.</li><li>Stores replicated paint command history when multiplayer paint replication is enabled.</li></ul><h2 id="required-setup" tabindex="-1">Required Setup <a class="header-anchor" href="#required-setup" aria-label="Permalink to &quot;Required Setup&quot;">​</a></h2><p>For a basic paintable mesh, you usually only need:</p><ul><li>A mesh actor in the level.</li><li><code>RuntimeMeshPaintTargetComponent</code> on that actor.</li><li>A material using the <code>Mesh Painting</code> material function.</li><li>Collision that blocks the painting trace channel, usually <code>Visibility</code>.</li></ul><p>The default render target settings are enough for a first test.</p><h2 id="runtime-target-settings" tabindex="-1">Runtime Target Settings <a class="header-anchor" href="#runtime-target-settings" aria-label="Permalink to &quot;Runtime Target Settings&quot;">​</a></h2><p>The <code>Runtime Target</code> section controls the render targets and material texture bindings used by the component.</p><p><img src="'+o+'" alt="Paint target runtime settings"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Mesh Targets</code></td><td>Optional list of named mesh components that can be painted.</td></tr><tr><td><code>Create Painted Material Settings Render Target</code></td><td>Creates the extra render target used for painted metallic and roughness data.</td></tr><tr><td><code>Runtime Render Target Width</code></td><td>Width of the runtime paint texture.</td></tr><tr><td><code>Runtime Render Target Height</code></td><td>Height of the runtime paint texture.</td></tr><tr><td><code>Runtime Render Target Format</code></td><td>Texture format used by the runtime render targets.</td></tr><tr><td><code>Initial Paint Color</code></td><td>Starting clear color for the color paint target.</td></tr><tr><td><code>Initial Material Settings Color</code></td><td>Starting clear color for the material settings target.</td></tr><tr><td><code>Painted Color Texture Parameter Name</code></td><td>Material texture parameter that receives the color paint target.</td></tr><tr><td><code>Painted Material Settings Texture Parameter Name</code></td><td>Material texture parameter that receives the material settings target.</td></tr><tr><td><code>Brush Preview Mask Texture Parameter Name</code></td><td>Material texture parameter that receives the GPU brush preview mask.</td></tr></tbody></table><p>In most cases, keep the texture parameter names at their defaults and set up the material through the plugin&#39;s <code>Mesh Painting</code> material function.</p><p>The default parameter names expected by the plugin material function are:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Purpose</th></tr></thead><tbody><tr><td><code>PaintedColorTexture</code></td><td>Runtime base color paint texture.</td></tr><tr><td><code>PaintedMaterialSettingsTexture</code></td><td>Runtime metallic/roughness paint texture.</td></tr><tr><td><code>BrushPreviewMaskTexture</code></td><td>Runtime brush preview ring mask.</td></tr></tbody></table><h2 id="mesh-targets" tabindex="-1">Mesh Targets <a class="header-anchor" href="#mesh-targets" aria-label="Permalink to &quot;Mesh Targets&quot;">​</a></h2><p>If the actor has a single mesh component, the paint target can resolve it automatically.</p><p>If the actor has multiple mesh components, use <code>Mesh Targets</code> to choose exactly which components should receive paint. The values are component names, such as <code>StaticMeshComponent0</code>.</p><p><img src="'+s+'" alt="Mesh Targets list"></p><p>If the list contains multiple valid meshes, the component creates runtime paint data for each selected mesh.</p><h2 id="uv-channel" tabindex="-1">UV Channel <a class="header-anchor" href="#uv-channel" aria-label="Permalink to &quot;UV Channel&quot;">​</a></h2><p><code>UVChannel</code> decides which UV channel is used for hit UV calculation and GPU paint projection.</p><p>This must match the <code>UV Index</code> used by the <code>Mesh Painting</code> material function. If these values do not match, paint can appear offset, stretched, or on the wrong part of the mesh.</p><h2 id="max-skeletal-mesh-uv-fallback-distance" tabindex="-1">Max Skeletal Mesh UV Fallback Distance <a class="header-anchor" href="#max-skeletal-mesh-uv-fallback-distance" aria-label="Permalink to &quot;Max Skeletal Mesh UV Fallback Distance&quot;">​</a></h2><p><code>Max Skeletal Mesh UVFallback Distance</code> is only used by skeletal mesh UV fallback resolution.</p><ul><li><code>0.0</code> disables the distance limit.</li><li>A value greater than <code>0.0</code> rejects fallback results if the resolved triangle is farther than that distance from the hit point.</li></ul><p>This does not control brush size or preview size.</p><p>The current GPU projected painting path avoids using skeletal fallback during the normal brush hot path. Keep this setting at its default unless you are calling lower-level hit resolving functions that explicitly need fallback behavior.</p><h2 id="uv-island-clip" tabindex="-1">UV Island Clip <a class="header-anchor" href="#uv-island-clip" aria-label="Permalink to &quot;UV Island Clip&quot;">​</a></h2><p><code>Clip Brush to UVIsland</code> keeps large brushes from painting unrelated UV islands when the brush overlaps seams in UV space.</p><p>Keep it enabled for most meshes, especially:</p><ul><li>Characters with many UV islands.</li><li>Cubes or hard-surface meshes with separated UV faces.</li><li>Large brush sizes.</li><li>Visible seam areas.</li></ul><p><code>UVIsland Connection Tolerance</code> controls how close UV edges need to be before they are treated as connected. The default is usually correct; only change it if your mesh has unusual UV precision issues.</p><h2 id="replication-settings" tabindex="-1">Replication Settings <a class="header-anchor" href="#replication-settings" aria-label="Permalink to &quot;Replication Settings&quot;">​</a></h2><p>The replication settings are used when the paint target should work in multiplayer.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Replicate Runtime Paint</code></td><td>Enables replicated paint commands for this target.</td></tr><tr><td><code>Auto Enable Owner Replication</code></td><td>Lets the component enable replication on the owner actor on authority.</td></tr><tr><td><code>Max Replicated Paint Commands</code></td><td>Limits stored paint history. <code>0</code> keeps full history for late join.</td></tr><tr><td><code>Replicated Paint Replay Commands Per Tick</code></td><td>Controls how many stored commands are replayed each tick on clients.</td></tr><tr><td><code>Max Replicated Paint Distance</code></td><td>Optional server validation distance. <code>0</code> disables this limit.</td></tr><tr><td><code>Max Replicated Brush Size</code></td><td>Maximum brush size accepted by the server.</td></tr></tbody></table><p>For more details, see <a href="/MeshPaintingDoc/systems/multiplayer">Multiplayer</a>.</p><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><p>The component exposes paint-specific Blueprint events in the <code>Runtime Mesh Painting | Events</code> category. Unreal also shows the standard Actor Component activation events in the same Details panel.</p><p><img src="'+d+'" alt="RuntimeMeshPaintTargetComponent events"></p><table tabindex="0"><thead><tr><th>Event</th><th>When It Fires</th><th>Typical Use</th></tr></thead><tbody><tr><td><code>OnBrushSettingsApplied</code></td><td>After <code>ApplyBrushMaterialSettings</code> stores and clamps the new brush material settings on this target.</td><td>React when another system applies color, opacity, metallic, roughness, or erase settings directly to the target.</td></tr><tr><td><code>OnPaintApplied</code></td><td>After a paint command is successfully applied to this target. This also fires when replicated paint commands are replayed locally.</td><td>Mark the mesh as dirty, update save state, trigger small effects, or refresh UI that depends on the latest painted result.</td></tr><tr><td><code>OnComponentActivated</code></td><td>Inherited Unreal component event fired when the component is activated.</td><td>Use only for normal component activation logic, not for detecting a paint stroke.</td></tr><tr><td><code>OnComponentDeactivated</code></td><td>Inherited Unreal component event fired when the component is deactivated.</td><td>Use only for normal component deactivation logic, not for paint completion.</td></tr></tbody></table><p>Use <code>OnPaintApplied</code> when you need to know that actual painting happened. Changing brush color or settings by itself should not be treated as a paint event.</p><h2 id="useful-blueprint-functions" tabindex="-1">Useful Blueprint Functions <a class="header-anchor" href="#useful-blueprint-functions" aria-label="Permalink to &quot;Useful Blueprint Functions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Function</th><th>Use</th></tr></thead><tbody><tr><td><code>InitializeRuntimePaintTarget</code></td><td>Creates runtime render targets and applies them to target materials. Usually called automatically at runtime.</td></tr><tr><td><code>SetTargetMesh</code></td><td>Sets a single mesh component as the paint target.</td></tr><tr><td><code>SetMeshTargets</code></td><td>Sets multiple mesh components as paint targets.</td></tr><tr><td><code>AddMeshTarget</code></td><td>Adds one mesh component to the target list.</td></tr><tr><td><code>ClearMeshTargets</code></td><td>Clears the configured mesh target list.</td></tr><tr><td><code>PaintAtHitWithSettings</code></td><td>Applies paint from an existing hit result and brush settings.</td></tr><tr><td><code>PaintUnderCursorWithSettings</code></td><td>Finds a paint hit under the cursor and applies paint.</td></tr><tr><td><code>SamplePaintedSurfaceColor</code></td><td>Samples the painted color under a hit result for color picking.</td></tr></tbody></table><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ul><li>The actor has multiple mesh components but <code>Mesh Targets</code> is empty or points to the wrong component name.</li><li>The material does not use the <code>Mesh Painting</code> material function.</li><li>The material <code>UV Index</code> does not match <code>UVChannel</code>.</li><li>The mesh does not block the painting trace channel.</li><li><code>Clip Brush to UVIsland</code> is disabled and large brushes paint across unrelated UV islands.</li><li>Multiplayer is expected to work, but the target actor or runtime paint replication is disabled.</li></ul>',49)])])}const y=e(l,[["render",c]]);export{f as __pageData,y as default};
